package main

import (
	"fmt"
)

func isLeap(year int) int {
	if year%4 == 0 && year%100 != 0 || year%400 == 0 {
		return 29
	}
	return 28
}

func daysInMonth(year int) [12]int {
	feb := isLeap(year)
	return [12]int{31, feb, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31}
}

func noOfDaysRemaining(mon, year int) int {
	days := 0
	dim := daysInMonth(year)
	for i := mon - 1; i < 12; i++ {
		days += dim[i]
	}
	return days
}

func noOfDaysPassed(mon, year int) int {
	days := 0
	dim := daysInMonth(year)
	for i := 0; i < mon; i++ {
		days += dim[i]
	}
	return days
}

func noOfDays(year int) int {
	return 31*7 + 30*4 + isLeap(year)
}

func main() {
	var yy1, mm1, dd1, yy2, mm2, dd2 int
	fmt.Scanf("%d:%d:%d", &yy1, &mm1, &dd1)
	fmt.Scanf("%d:%d:%d", &yy2, &mm2, &dd2)

	var y1, m1, d1, y2, m2, d2 int
	if yy2 > yy1 {
		y1, m1, d1 = yy1, mm1, dd1
		y2, m2, d2 = yy2, mm2, dd2
	} else {
		y1, m1, d1 = yy2, mm2, dd2
		y2, m2, d2 = yy1, mm1, dd1
	}

	nodA := noOfDaysRemaining(m1, y1)
	nodC := noOfDaysPassed(m2-1, y2)

	nodB := 0
	for i := y1 + 1; i <= y2-1; i++ {
		nodB += noOfDays(i)
	}

	nod := (nodA - d1 + 1) + (nodC + d2) + nodB - 1

	if yy1 == yy2 {
		if mm2 > mm1 {
			nod = (noOfDaysRemaining(mm1, yy1) - dd1 + 1) - (noOfDaysRemaining(mm2, yy2) - dd2 + 1)
		} else if mm2 < mm1 {
			nod = (noOfDaysRemaining(mm2, yy2) - dd2 + 1) - (noOfDaysRemaining(mm1, yy1) - dd1 + 1)
		} else {
			if dd1 > dd2 {
				nod = dd1 - dd2
			} else {
				nod = dd2 - dd1
			}
		}
	}

	fmt.Printf("%d", nod)
}

